function maxSubArray(nums: number[]): number {
  // cur — лучшая сумма подмассива, который заканчивается в текущей позиции
  let cur = 0;
  // best — лучшая сумма среди всех подмассивов; -Infinity, чтобы
  // корректно обработать массив из одних отрицательных чисел
  let best = -Infinity;

  for (const x of nums) {
    // Либо продолжаем предыдущий отрезок, либо начинаем новый с x:
    // отрицательная накопленная сумма только уменьшила бы результат
    cur = Math.max(x, cur + x);
    best = Math.max(best, cur);
  }

  return best;
}

// Время: O(n) — один проход
// Память: O(1)
